mapper.select:
SELECT 
FROM fund_sync_run
WHERE 1 = 1

    AND fetch_batch_id = #{bo.fetchBatchId}


    AND dataset = #{bo.dataset}


    AND scope_type = #{bo.scopeType}


    AND scope_value = #{bo.scopeValue}


    AND (scope_type = #{bo.syncScope} OR CONCAT(scope_type, ':', COALESCE(scope_value, '')) = #{bo.syncScope})


    AND scope_type = 'FUND_CODE'
    AND scope_value = #{bo.fundCode}


    AND state = #{bo.state}


    AND state = #{bo.status}


    AND (
        (#{bo.syncType} = 'INCREMENTAL' AND scope_value = 'incremental')
        OR (#{bo.syncType} = 'FULL_INIT' AND scope_type = 'ALL')
        OR (#{bo.syncType} = 'LAZY_LOAD' AND scope_type = 'FUND_CODE')
    )


    AND started_at >= #{bo.startedAtStart}


    AND started_at <= #{bo.startedAtEnd}

ORDER BY started_at DESC, id DESC

SELECT 
FROM fund_sync_run
WHERE state = 'RUNNING'

    AND dataset = #{dataset}


    AND scope_type = #{scopeType}


    AND scope_value = #{scopeValue}

ORDER BY started_at DESC

SELECT dataset, source, source_time, business_date, scope_type, scope_value, state, quality_status, fetch_batch_id, data_version, checksum, started_at, finished_at, success_count, rejected_count, failed_count, retry_count, upstream_latency_ms, stale_count, cache_invalidated_count, error_code, error_message FROM fund_sync_run WHERE dataset = #{dataset}
AND scope_type = #{scopeType}
AND scope_value = #{scopeValue}
ORDER BY started_at DESC, id DESC LIMIT 1
